/**
 * Mid-run host MCP OAuth: mint an authUrl, finish on the public serve
 * callback (file tokens). Deployment secrets persist from the
 * authenticated park, not from that callback.
 *
 * CLI `mcp oauth` still uses the loopback callback. This path is recovery
 * and first-use without a separate `--store` step.
 */
import { UnauthorizedError } from "@modelcontextprotocol/sdk/client/auth.js";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { SSEClientTransport } from "@modelcontextprotocol/sdk/client/sse.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { describeError } from "./describe-error.js";
import { LOG_PREFIX } from "./distribution.js";
import { createHostMcpOAuthProvider, FileMcpOAuthStore, MCP_OAUTH_CALLBACK_URL, } from "./mcp-oauth.js";
import { resolveHostedMcpOauthSecretsTarget, upsertHostMcpOauthSecrets, } from "./mcp-oauth-persist.js";
export function mcpOauthServeCallbackPath(basePath = "") {
    return `${basePath}/v1/mcp-oauth/callback`;
}
export function mcpOauthServeCallbackUrl(origin, basePath = "") {
    return `${origin.replace(/\/$/, "")}${mcpOauthServeCallbackPath(basePath)}`;
}
export async function beginHostMcpOauth(args) {
    let authorizationUrl;
    const provider = await createHostMcpOAuthProvider({
        identifier: args.connection,
        resourceUrl: args.url,
        store: args.store,
        redirectUrl: args.redirectUrl,
        onRedirect: (url) => {
            authorizationUrl = url;
        },
    });
    const client = new Client({ name: "agent-sdk-mcp-oauth", version: "0.1.0" });
    const url = new URL(args.url);
    const requestInit = args.headers === undefined ? undefined : { headers: args.headers };
    const makeTransport = () => {
        if (args.type === "sse") {
            return new SSEClientTransport(url, {
                authProvider: provider,
                requestInit,
            });
        }
        return new StreamableHTTPClientTransport(url, {
            authProvider: provider,
            requestInit,
        });
    };
    const transport = makeTransport();
    try {
        await client.connect(transport);
        await client.close().catch(() => undefined);
        return { status: "authorized" };
    }
    catch (error) {
        if (!(error instanceof UnauthorizedError)) {
            throw error;
        }
    }
    const redirect = authorizationUrl ?? provider.lastRedirectUrl;
    if (redirect === undefined) {
        throw new Error(`Auth required for "${args.connection}" but no authorization URL was provided.`);
    }
    const state = redirect.searchParams.get("state") ?? "";
    if (state === "") {
        throw new Error(`Auth required for "${args.connection}" but the authorization URL had no state.`);
    }
    return {
        status: "needs_auth",
        authUrl: redirect.toString(),
        state,
        finish: async (code) => {
            await transport.finishAuth(code);
            await transport.close?.().catch(() => undefined);
        },
        abort: async () => {
            await transport.close?.().catch(() => undefined);
        },
    };
}
export class McpOauthOnDemandHub {
    constructor() {
        this.attempts = new Map();
        this.completed = new Map();
        this.finishing = new Map();
        this.aborted = new Set();
    }
    async mint(args) {
        const redirectUrl = this.callbackUrl ?? MCP_OAUTH_CALLBACK_URL;
        const store = this.fileStore();
        const started = await beginHostMcpOauth({
            connection: args.connection,
            url: args.url,
            type: args.type,
            headers: args.headers,
            redirectUrl,
            store,
        });
        if (started.status === "authorized") {
            return { authorized: true };
        }
        this.attempts.set(started.state, {
            connection: args.connection,
            resourceUrl: args.url,
            finish: started.finish,
            abort: started.abort,
            sessionId: args.sessionId,
        });
        return { authUrl: started.authUrl, state: started.state };
    }
    async abortCall(sessionId, callId) {
        await this.dropWhere((attempt) => attempt.sessionId === sessionId && attempt.callId === callId, true);
    }
    async abortSession(sessionId) {
        await this.dropWhere((attempt) => attempt.sessionId === sessionId, false);
    }
    async close() {
        await this.dropWhere(() => true, true);
    }
    async dropWhere(match, includeCompleted) {
        const jobs = [];
        for (const [state, attempt] of this.attempts) {
            if (!match(attempt)) {
                continue;
            }
            this.aborted.add(state);
            this.attempts.delete(state);
            jobs.push(attempt.abort().catch(() => undefined));
        }
        if (includeCompleted) {
            for (const [state, attempt] of this.completed) {
                if (!match(attempt)) {
                    continue;
                }
                this.aborted.add(state);
                this.completed.delete(state);
            }
        }
        await Promise.all(jobs);
    }
    bind(state, sessionId, callId) {
        const live = this.attempts.get(state);
        if (live !== undefined) {
            live.sessionId = sessionId;
            live.callId = callId;
            return "pending";
        }
        const done = this.completed.get(state);
        if (done !== undefined) {
            done.sessionId = sessionId;
            done.callId = callId;
            return "already_done";
        }
        return "unknown";
    }
    async complete(state, code) {
        if (this.aborted.has(state)) {
            throw new Error("Unknown OAuth state.");
        }
        const pending = this.finishing.get(state);
        if (pending !== undefined) {
            return await pending;
        }
        const attempt = this.attempts.get(state);
        if (attempt === undefined) {
            throw new Error("Unknown OAuth state.");
        }
        const run = this.finishAttempt(state, attempt, code);
        this.finishing.set(state, run);
        return await run;
    }
    async finishAttempt(state, attempt, code) {
        try {
            await attempt.finish(code);
            this.attempts.delete(state);
            if (!this.aborted.has(state)) {
                this.completed.set(state, attempt);
            }
            return {
                connection: attempt.connection,
                sessionId: attempt.sessionId,
                callId: attempt.callId,
            };
        }
        finally {
            this.finishing.delete(state);
        }
    }
    fileStore() {
        this.store ??= new FileMcpOAuthStore();
        return this.store;
    }
    async persistFor(connection, resourceUrl) {
        const target = this.secrets ?? resolveHostedMcpOauthSecretsTarget(this.secretsBind ?? {});
        if (target === undefined) {
            return;
        }
        const store = this.fileStore();
        const tokens = await store.loadTokens(connection, resourceUrl);
        if (tokens === undefined || tokens.access_token.trim() === "") {
            return;
        }
        const client = await store.loadClientInformation(connection, resourceUrl);
        try {
            const names = await upsertHostMcpOauthSecrets({
                connection,
                tokens,
                clientId: client?.client_id,
                target,
            });
            this.logger?.(`${LOG_PREFIX} MCP OAuth tokens stored on the deployment (${names.join(", ")}).`);
        }
        catch (error) {
            this.logger?.(`${LOG_PREFIX} MCP OAuth persist failed for "${connection}": ${describeError(error)}`);
        }
    }
    async handleCallback(request) {
        const url = new URL(request.url);
        const code = url.searchParams.get("code");
        const state = url.searchParams.get("state") ?? "";
        if (this.aborted.has(state)) {
            return oauthHtml(404, "<h1>Not found</h1>");
        }
        if (this.completed.has(state)) {
            return oauthHtml(200, "<h1>Authorized</h1><p>Return to the agent.</p>");
        }
        if (!this.attempts.has(state)) {
            return oauthHtml(404, "<h1>Not found</h1>");
        }
        if (code !== null && code !== "") {
            try {
                await this.complete(state, code);
            }
            catch {
                return oauthHtml(400, "<h1>Authorization failed</h1>");
            }
            if (this.aborted.has(state)) {
                return oauthHtml(404, "<h1>Not found</h1>");
            }
            return oauthHtml(200, "<h1>Authorized</h1><p>Return to the agent.</p>");
        }
        return oauthHtml(400, "<h1>Authorization failed</h1>");
    }
}
function oauthHtml(status, body) {
    return new Response(`<!doctype html><html><body>${body}</body></html>`, {
        status,
        headers: { "content-type": "text/html; charset=utf-8" },
    });
}
